/* Evaluates the After Effects expressions generated by src/host/hostscript.jsx against a mock
   of AE's expression environment, and checks them against the layout engine. */
const test = require("node:test");
const assert = require("node:assert");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const FntParser = require("../src/core/fntParser.js");
const { layoutText } = require("../src/core/layout.js");
const FntCounter = require("../src/core/counter.js");

const host = {};
vm.createContext(host);
vm.runInContext(fs.readFileSync(path.join(__dirname, "..", "src", "host", "hostscript.jsx"), "utf8"), host);

function loadFont() {
  const f = FntParser.parse(fs.readFileSync(path.join(__dirname, "..", "samples", "demo.fnt"), "utf8"));
  // make the digit metrics non-uniform so the glyph swap is really exercised
  const tweak = { 1: [7, 20, 4], 4: [2, 28, 6], 7: [1, 26, 3] };
  for (const [d, [xo, w, yo]] of Object.entries(tweak)) {
    const c = f.chars[48 + Number(d)];
    c.xoffset = xo; c.width = w; c.yoffset = yo;
  }
  return f;
}

// Mirrors createComp() in src/panel/js/main.js
function buildPayload(font, text, o) {
  const opts = { scale: o.s0, tracking: o.t0, lineHeight: o.lh0, overrides: o.overrides || {} };
  const L = layoutText(font, text, opts);
  const base = layoutText(font, text, { scale: 1, tracking: 0, lineHeight: 0, overrides: opts.overrides });
  const data = {
    s0: o.s0, t0: o.t0, lh0: o.lh0, Wb: base.width, Nw: Math.max.apply(null, base.counts), lines: L.lines,
    width: L.width, height: L.height, counter: null
  };
  data.glyphs = L.glyphs.map((g, i) => {
    const b = base.glyphs[i];
    return {
      char: g.char, index: g.index, sx: g.sx, sy: g.sy, sw: g.sw, sh: g.sh,
      relx: g.x + g.w / 2 - L.width / 2, rely: g.y + g.h / 2 - L.height / 2,
      scale: g.scale, rot: g.rot, P: b.x + b.w / 2, Q: b.y + b.h / 2, n: g.n, line: g.line
    };
  });
  if (o.counter) {
    const tb = FntCounter.digitTables(font);
    assert.ok(tb.ok, tb.reason);
    const N = FntCounter.annotate(L.glyphs);
    const dec = o.counter.dec;
    data.counter = {
      N, dec, zeros: !!o.counter.zeros, M: Math.max(0, N - dec - 1), t: tb.t, num0: FntCounter.typedNumber(text, dec)
    };
    data.glyphs.forEach((gl, i) => {
      const lg = L.glyphs[i], b = base.glyphs[i], def = font.chars[lg.id];
      gl.slot = lg.slot; gl.before = lg.before;
      if (lg.slot >= 0) {
        gl.cx1 = b.x + b.w / 2 - def.xoffset - def.width / 2;
        gl.y0 = b.y + b.h / 2 - def.yoffset - def.height / 2;
      }
    });
  }
  return { data, L };
}

// Runs an AE expression with a mocked controller.
function run(expr, value, ctrl) {
  const eff = { Size: ctrl.size, Tracking: ctrl.tracking, "Line Height": ctrl.lineHeight, Number: ctrl.number };
  const env = {
    thisLayer: { parent: { effect: (n) => () => eff[n] } },
    value: value,
    createPath: (pts) => ({ pts })
  };
  vm.createContext(env);
  // AE adds arrays element-wise
  const code = expr.replace("r = value + [dx, dy];", "r = [value[0] + dx, value[1] + dy];");
  return vm.runInContext(code, env);
}

const near = (a, b, msg) => assert.ok(Math.abs(a - b) < 1e-9, `${msg}: ${a} vs ${b}`);

test("size/tracking/line-height expressions match the layout engine (no counter)", () => {
  const font = loadFont();
  const { data, L } = buildPayload(font, "12\n50", { s0: 1.2, t0: 2, lh0: 130 });
  const s = 0.8, t = 7, lh = 160;
  const T = layoutText(font, "12\n50", { scale: s, tracking: t, lineHeight: lh });
  data.glyphs.forEach((g, i) => {
    const r = run(host.fntPosExpr(g, data), [g.relx, g.rely], { size: s * 100, tracking: t, lineHeight: lh });
    const w = T.glyphs[i];
    near(r[0], w.x + w.w / 2 - T.width / 2, "x " + i);
    near(r[1], w.y + w.h / 2 - T.height / 2, "y " + i);
  });
});

// Digits shown for a number, read back from the anchor expressions (each digit has a distinct anchor).
function shown(font, text, counterOpts, number, ctrl) {
  const { data } = buildPayload(font, text, { s0: 1, t0: 0, lh0: font.common.lineHeight, counter: counterOpts });
  const tb = FntCounter.digitTables(font).t;
  const out = [];
  data.glyphs.forEach((g) => {
    const c = Object.assign({ size: 100, tracking: 0, lineHeight: font.common.lineHeight, number }, ctrl || {});
    const opacity = run(host.fntVisExpr(data.counter, g), 100, c);
    let ch = g.char;
    if (g.slot >= 0) {
      const a = run(host.fntAnchorExpr(data.counter, g), [0, 0], c);
      const d = tb.sx.findIndex((x, k) => x + tb.sw[k] / 2 === a[0] && tb.sy[k] + tb.sh[k] / 2 === a[1]);
      ch = String(d);
    }
    out.push(opacity === 0 ? "_" : ch);
  });
  return out.join("");
}

test("counter: digits, leading zeros and separators follow the Number slider", () => {
  const font = loadFont();
  const opt = { dec: 0 };
  assert.strictEqual(shown(font, "1250", opt, 1250), "1250");
  assert.strictEqual(shown(font, "1250", opt, 37), "__37");
  assert.strictEqual(shown(font, "1250", opt, 0), "___0");
  assert.strictEqual(shown(font, "1250", opt, 99999), "9999"); // clamped to the slots available
  assert.strictEqual(shown(font, "1250", { dec: 0, zeros: true }, 37), "0037");
  // currency-like: prefix stays, thousands comma hides with its leading digits, "." and decimals stay
  const cur = { dec: 2 };
  assert.strictEqual(shown(font, "+1,250.00", cur, 1250), "+1,250.00");
  assert.strictEqual(shown(font, "+1,250.00", cur, 37.5), "+___37.50");
  assert.strictEqual(shown(font, "+1,250.00", cur, 0.37), "+____0.37");
  assert.strictEqual(shown(font, "+1,250.00", cur, 1234.5), "+1,234.50");
});

test("counter: positions equal a fresh layout of the displayed number (non-uniform digit metrics)", () => {
  const font = loadFont();
  const text = "1250";
  const ov = { 1: { kern: 3, dy: 2, scale: 1.5 } };
  const { data } = buildPayload(font, text, { s0: 1.3, t0: 2, lh0: 60, overrides: ov, counter: { dec: 0 } });
  const s = 0.9, t = 5, lh = 80;
  for (const n of [1250, 4713, 8, 1000, 7777]) {
    const str = String(Math.min(n, 9999)).padStart(4, "0");
    const E = layoutText(font, str, { scale: s, tracking: t, lineHeight: lh, overrides: ov });
    data.glyphs.forEach((g, i) => {
      const r = run(host.fntPosExpr(g, data), [g.relx, g.rely], { size: s * 100, tracking: t, lineHeight: lh, number: n });
      const w = E.glyphs[i];
      // the block stays centred on the typed text's block; all digits have the same advance here
      near(r[0], w.x + w.w / 2 - E.width / 2, `x n=${n} i=${i}`);
      near(r[1], w.y + w.h / 2 - E.height / 2, `y n=${n} i=${i}`);
    });
  }
});

test("counter: mask expression builds the digit's rectangle", () => {
  const font = loadFont();
  const { data } = buildPayload(font, "1250", { s0: 1, t0: 0, lh0: 54, counter: { dec: 0 } });
  const t = FntCounter.digitTables(font).t;
  const g = data.glyphs[0]; // slot 0
  const r = run(host.fntMaskExpr(data.counter, g), 0, { size: 100, tracking: 0, lineHeight: 54, number: 7000 });
  const d = 7;
  assert.deepStrictEqual(JSON.parse(JSON.stringify(r.pts)), [
    [t.sx[d], t.sy[d]], [t.sx[d] + t.sw[d], t.sy[d]],
    [t.sx[d] + t.sw[d], t.sy[d] + t.sh[d]], [t.sx[d], t.sy[d] + t.sh[d]]
  ]);
});

test("counter helpers", () => {
  assert.strictEqual(FntCounter.detectDecimals("$1,250.00"), 2);
  assert.strictEqual(FntCounter.detectDecimals("1250"), 0);
  assert.strictEqual(FntCounter.detectDecimals("3.5%"), 1);
  assert.strictEqual(FntCounter.typedNumber("$1,250.00", 2), 1250);
  assert.strictEqual(FntCounter.typedNumber("abc", 0), 0);
  const bad = FntParser.parse('common lineHeight=10 base=8\npage id=0 file="a.png"\nchar id=48 x=0 y=0 width=3 height=3 xoffset=0 yoffset=0 xadvance=4');
  assert.strictEqual(FntCounter.digitTables(bad).ok, false);
});
